WITH customer_totals AS (
  SELECT customer_id, SUM(amount) AS total
  FROM `sales.orders`
  GROUP BY customer_id
)
SELECT customer_id FROM customer_totals WHERE total > 1000;

SELECT order_id FROM `sales.orders` WHERE status = "shipped"
UNION ALL
SELECT order_id FROM `sales.orders` WHERE status = "delivered";

WITH ranked AS (
  SELECT order_id, customer_id,
    ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY amount DESC) AS rn
  FROM `sales.orders`
)
SELECT order_id FROM ranked WHERE rn = 1;

SELECT order_id, attrs.channel AS channel
FROM `sales.orders`
WHERE attrs.channel = "web";
